#Preview("Icon grid") {
    let columns = [GridItem(.adaptive(minimum: 72), spacing: GravitySpacing.space12)]
    return ScrollView {
        LazyVGrid(columns: columns, spacing: GravitySpacing.space12) {
            ForEach(GravityIcon.allCases) { icon in
                VStack(spacing: GravitySpacing.space4) {
                    icon.image
                        .resizable()
                        .scaledToFit()
                        .frame(width: 24, height: 24)
                        .foregroundStyle(GravityColors.text)
                        .frame(width: 56, height: 56)
                        .background(GravityColors.bgFillSecondary, in: RoundedRectangle(cornerRadius: GravityRadius.r12))
                    Text(icon.rawValue.replacingOccurrences(of: "icon-", with: ""))
                        .gravityTextStyle(GravityTypography.badge)
                        .foregroundStyle(GravityColors.textTertiary)
                        .lineLimit(1)
                        .truncationMode(.middle)
                }
            }
        }
        .padding(GravitySpacing.space16)
    }
    .background(GravityColors.bg)
}
